          }
          if (deviceInfo.isTv !== undefined) {
            this.path = EnableNotificationDialog.TV_DIALOG_PATH;
            console.info(TAG, 'tv request');
          }
          if (deviceInfo.isCar !== undefined) {
            this.path = EnableNotificationDialog.CAR_DIALOG_PATH;
